const MAX_WORDS = 4;
const FOLDED: Map<string, string> = new Map(Object.entries(PLACE_TO_ISO2).map(([k, v]) => [normText(k), v]));

/** Infer ISO-2 countries from free-text locations. Conservative: whole-phrase matches only. */
export function countriesFromText(locations: string[]): string[] {
    const found = new Set<string>();
    for (const loc of locations) {
        const hits = new Set<string>();
        const words = normText(loc).split(' ').filter(Boolean);
        for (let i = 0; i < words.length; i++) {
            for (let n = Math.min(MAX_WORDS, words.length - i); n >= 1; n--) {
                const phrase = words.slice(i, i + n).join(' ');
                if (n === 1 && phrase.length <= 2 && phrase !== 'us' && phrase !== 'uk') continue;
                const hit = FOLDED.get(phrase);
                if (hit) {
                    hits.add(hit);
                    i += n - 1;
                    break;
                }
            }
        }
        if (!hits.size) {
            // "Springfield, IL" / "Waterloo, ON": a 2-letter code after a comma; US/CA region codes win over ISO-2.
            for (const part of loc.split(/[,;/|]|\s[-–]\s/).slice(1)) {
                const code = part.trim();
                if (!/^[A-Za-z]{2}$/.test(code)) continue;
                const region = REGION_ABBR_TO_ISO2[code.toLowerCase()];
                if (region) hits.add(region);
                else if (ISO2.has(code.toUpperCase())) hits.add(code.toUpperCase());
            }
        }
        for (const h of hits) found.add(h);
    }
    return [...found];
}

/** Map a country name or ISO-3/ISO-2 code from an ATS address field to ISO-2. */
export function countryToIso2(v: string | null | undefined): string | null {
    if (!v) return null;
    const s = v.trim();
    if (/^[A-Za-z]{2}$/.test(s) && ISO2.has(s.toUpperCase())) return s.toUpperCase();
    return FOLDED.get(normText(s)) ?? null;
}
